// ============================================================
// DISC-GJ v1.0 — Calificador para Google Apps Script
// GastroJobs — Propiedad de The Hap&D Co.
// ============================================================
//
// ENTRADA: respuestas = {
//   columna_I: [
//     { grupo: 'G01', A: 3, B: 4, C: 1, D: 2 },  // valores 1-4
//     ...
//   ],
//   columna_II: [ ... ],
//   columna_III: [ ... ]
// }
//
// SALIDA: objeto con puntajes normalizados 0-100 y perfiles dominantes
// ============================================================

const CLAVE_DISC_GJ = {
  G01:{A:'D',B:'I',C:'S',D:'C'},
  G02:{A:'D',B:'I',C:'S',D:'C'},
  G03:{A:'D',B:'I',C:'S',D:'C'},
  G04:{A:'D',B:'I',C:'S',D:'C'},
  G05:{A:'D',B:'I',C:'S',D:'C'},
  G06:{A:'D',B:'I',C:'S',D:'C'},
  G07:{A:'D',B:'I',C:'S',D:'C'},
  G08:{A:'D',B:'I',C:'S',D:'C'},
  G09:{A:'D',B:'I',C:'S',D:'C'},
  G10:{A:'D',B:'I',C:'S',D:'C'},
  G11:{A:'D',B:'I',C:'S',D:'C'},
  G12:{A:'D',B:'I',C:'S',D:'C'},
  G13:{A:'D',B:'I',C:'S',D:'C'},
  G14:{A:'D',B:'I',C:'S',D:'C'},
  G15:{A:'D',B:'I',C:'S',D:'C'},
  G16:{A:'D',B:'I',C:'S',D:'C'},
  G17:{A:'D',B:'I',C:'S',D:'C'},
  G18:{A:'D',B:'I',C:'S',D:'C'},
  G19:{A:'D',B:'I',C:'S',D:'C'},
  G20:{A:'D',B:'I',C:'S',D:'C'},
  G21:{A:'D',B:'I',C:'S',D:'C'},
  G22:{A:'D',B:'I',C:'S',D:'C'},
  G23:{A:'D',B:'I',C:'S',D:'C'},
  G24:{A:'D',B:'I',C:'S',D:'C'}
};

function calcularDISC_GJ(respuestas) {
  const COLUMNAS = ['columna_I', 'columna_II', 'columna_III'];
  const resultado = {};

  COLUMNAS.forEach(col => {
    const scores = { D: 0, I: 0, S: 0, C: 0 };

    respuestas[col].forEach(fila => {
      const grupo = fila.grupo;
      const clave = CLAVE_DISC_GJ[grupo];
      if (!clave) return;

      // A, B, C, D — cada uno tiene un valor 1-4 asignado por el candidato
      ['A','B','C','D'].forEach(opcion => {
        const dim = clave[opcion];
        const puntos = fila[opcion];
        // Validar que el valor sea entre 1 y 4
        if (typeof puntos === 'number' && puntos >= 1 && puntos <= 4) {
          scores[dim] += puntos;
        }
      });
    });

    // Normalizar a 0-100: (bruto - 24) / 72 * 100
    const normalizado = {};
    Object.keys(scores).forEach(dim => {
      normalizado[dim] = Math.round((scores[dim] - 24) / 72 * 100);
    });

    // Perfil dominante = dimensión con mayor puntaje
    const dominante = Object.keys(normalizado).reduce((a, b) =>
      normalizado[a] >= normalizado[b] ? a : b
    );

    resultado[col] = {
      brutos: scores,
      normalizados: normalizado,
      dominante: dominante,
      perfil_label: col === 'columna_I' ? 'Mascara' :
                    col === 'columna_II' ? 'Natural' : 'Bajo_presion'
    };
  });

  // Calcular índice de congruencia entre Natural y Bajo presión
  const natural = resultado['columna_II'].dominante;
  const presion = resultado['columna_III'].dominante;
  resultado['meta'] = {
    perfil_natural: natural,
    perfil_bajo_presion: presion,
    congruente: natural === presion,
    nota: natural === presion
      ? 'El candidato mantiene su estilo bajo presión.'
      : 'El candidato cambia su estilo bajo presión: de ' + natural + ' a ' + presion + '.'
  };

  return resultado;
}

// ============================================================
// VALIDADOR DE RESPUESTAS (usar antes de calcular)
// Verifica que cada grupo tenga exactamente los valores 1,2,3,4
// ============================================================
function validarRespuestasDISC(respuestas) {
  const COLUMNAS = ['columna_I', 'columna_II', 'columna_III'];
  const errores = [];

  COLUMNAS.forEach(col => {
    if (!respuestas[col] || respuestas[col].length !== 24) {
      errores.push(col + ': debe tener exactamente 24 grupos.');
      return;
    }
    respuestas[col].forEach(fila => {
      const valores = ['A','B','C','D'].map(o => fila[o]).sort((a,b) => a-b);
      if (JSON.stringify(valores) !== JSON.stringify([1,2,3,4])) {
        errores.push(col + ' - ' + fila.grupo + ': los valores deben ser exactamente 1,2,3,4 sin repetir.');
      }
    });
  });

  return {
    valido: errores.length === 0,
    errores: errores
  };
}

